From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:40:06 +0100
Subject: [PATCH] applets/pager: switch all screens when the pager shows all
 screens

With per-screen virtual desktops, clicking a desktop only switched the
screen the pager is on, although each cell shows every screen. When the
pager shows all screens, switch every screen to the clicked desktop.

BUG: 522014
---
 applets/pager/pagermodel.cpp | 9 +++++++--
 1 file changed, 7 insertions(+), 2 deletions(-)

diff --git a/applets/pager/pagermodel.cpp b/applets/pager/pagermodel.cpp
index 6e476f3d15..c98284dec5 100644
--- a/applets/pager/pagermodel.cpp
+++ b/applets/pager/pagermodel.cpp
@@ -496,10 +496,15 @@ void PagerModel::changePage(int page)
         if (d->pagerType == VirtualDesktops) {
             QVariant desktopId = d->virtualDesktopInfo->desktopIds().at(page);

-            if (!d->screenName.isEmpty()) {
+            if (d->screenName.isEmpty()) {
+                d->virtualDesktopInfo->requestActivate(desktopId);
+            } else if (d->showOnlyCurrentScreen) {
                 d->virtualDesktopInfo->requestActivateOnScreen(desktopId, d->screenName);
             } else {
-                d->virtualDesktopInfo->requestActivate(desktopId);
+                // Each page shows all screens, so switch all of them
+                for (const auto screens = qGuiApp->screens(); auto screen : screens) {
+                    d->virtualDesktopInfo->requestActivateOnScreen(desktopId, screen->name());
+                }
             }
         } else {
             const QStringList &runningActivities = d->activityInfo->runningActivities();
